<?php
declare(strict_types=1);
require_once __DIR__ . '/patient-auth.php';
require_once __DIR__ . '/payment-display.php';
$patient = require_patient();
$patientSince = strtotime((string) ($patient['created_at'] ?? 'now'));
$callQuery = db()->prepare("SELECT room_id, doctor_email, created_at FROM telemedicine_calls WHERE patient_id = ? AND status = 'waiting' AND expires_at > CURRENT_TIMESTAMP ORDER BY created_at DESC");
$callQuery->execute([$patient['id']]);
$waitingCalls = $callQuery->fetchAll();
$pdo = db();
$services = $pdo->query(
    'SELECT s.id, s.name, s.price_rwf, GROUP_CONCAT(pm.method SEPARATOR \',\') AS methods
     FROM services s
     LEFT JOIN service_payment_methods pm ON pm.service_id = s.id
     WHERE s.active = TRUE
     GROUP BY s.id, s.name, s.price_rwf
     ORDER BY s.name'
)->fetchAll();
$paymentDestinationQuery = $pdo->query('SELECT * FROM payment_destinations WHERE id = 1');
$paymentDestinations = $paymentDestinationQuery->fetch() ?: [];
$paymentMethodLabels = [
    'mtn_momo' => 'MTN Mobile Money',
    'airtel_money' => 'Airtel Money',
    'bank_transfer' => 'Bank transfer',
    'cash' => 'Cash',
];
$doctors = $pdo->query("SELECT full_name, email FROM staff_users WHERE role = 'doctor' ORDER BY full_name")->fetchAll();
$appointmentQuery = $pdo->prepare("SELECT a.id, a.status, a.appointment_type, a.preferred_at, a.created_at, a.doctor_email, s.name AS service_name, u.full_name AS doctor_name FROM appointment_requests a INNER JOIN services s ON s.id = a.service_id LEFT JOIN staff_users u ON u.email = a.doctor_email WHERE a.patient_id = ? ORDER BY COALESCE(a.preferred_at, a.created_at) DESC");
$appointmentQuery->execute([$patient['id']]);
$patientAppointments = $appointmentQuery->fetchAll();
$activeAppointments = array_filter($patientAppointments, static fn (array $item): bool => in_array($item['status'], ['new', 'contacted', 'scheduled'], true) && (!$item['preferred_at'] || strtotime($item['preferred_at']) >= time()));
$pastAppointments = array_filter($patientAppointments, static fn (array $item): bool => $item['status'] === 'cancelled' || ($item['preferred_at'] && strtotime($item['preferred_at']) < time()));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="patient-csrf" content="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><title>Patient portal | <?= htmlspecialchars(SITE_NAME) ?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/styles.css"></head><body class="dashboard-page"><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.php"><span class="brand-mark">IV</span><span><strong>Innovatio</strong><small>Vitalis Ltd</small></span></a><div class="dashboard-user"><span><?= htmlspecialchars($patient['name']) ?></span><a class="button button-small" href="account-settings.php">Account settings</a><a class="button button-small" href="patient_logout.php">Sign out</a></div></div></header><main class="dashboard-main container"><div class="dashboard-heading" id="patient-home"><div><p class="eyebrow">Patient portal</p><h1>Hello, <em><?= htmlspecialchars(explode(' ', trim($patient['name']))[0]) ?>.</em></h1><p>Your account profile and next steps for care.</p></div><span class="role-badge">Patient</span></div><nav class="doctor-dashboard-nav" aria-label="Patient dashboard sections"><a href="#patient-home">Dashboard home</a><a href="#patient-video">Video consultation</a><a href="#patient-records">Medical records</a><a href="#patient-appointments">Appointments</a><a href="#patient-chat">Chat &amp; files</a><a href="#patient-payments">Payments</a><a href="#patient-support">Support</a><a href="#patient-settings">Settings</a></nav><div class="patient-profile-setup"><span class="profile-photo-preview" data-profile-photo><span>+</span></span><div><strong>Set up your profile picture</strong><p>Choose an image to preview on this device. It will not be uploaded or saved.</p><label class="button button-small" for="patient-profile-picture">Choose photo</label><input id="patient-profile-picture" class="sr-only" type="file" accept="image/*" data-profile-picture></div></div><section class="stat-grid stat-grid-staff patient-profile-stats" aria-label="Patient profile"><article class="stat-card"><span>Account status</span><strong class="patient-status">Active</strong></article><article class="stat-card"><span>Profile created</span><strong class="patient-date"><?= htmlspecialchars(date('j M Y', $patientSince)) ?></strong></article><article class="stat-card"><span>Signed in as</span><strong class="patient-email"><?= htmlspecialchars($patient['email']) ?></strong></article></section><section class="patient-calls" id="patient-video"><div class="dashboard-section-heading"><div><p class="eyebrow">Video care</p><h2>Calls for <em>you.</em></h2></div></div><?php if (!$waitingCalls): ?><p class="empty-state">No video consultations are waiting. Your clinician will let you know when a call is ready.</p><?php else: ?><div class="patient-call-list"><?php foreach ($waitingCalls as $call): ?><article class="patient-call-card"><div><span class="status-badge status-new">Ready to join</span><h3>Video consultation</h3><p>From <?= htmlspecialchars($call['doctor_email']) ?> · <?= htmlspecialchars(date('j M Y, H:i', strtotime($call['created_at']))) ?></p></div><a class="button button-small" href="telemedicine-join.php?room=<?= rawurlencode($call['room_id']) ?>">Join consultation <span aria-hidden="true">&#8599;</span></a></article><?php endforeach; ?></div><?php endif; ?></section><section class="patient-appointments-workspace" id="patient-appointments"><div class="dashboard-section-heading"><div><p class="eyebrow">Bookings</p><h2>Appointments <em>&amp; requests.</em></h2></div></div>
<?php $appointmentNotice = (string) ($_GET['appointment'] ?? ''); if ($appointmentNotice !== ''): ?><p class="appointment-alert" role="status"><?php echo match ($appointmentNotice) { 'sent' => 'Your appointment request was sent. The care team will confirm availability.', 'rescheduled' => 'Your preferred time was updated. The care team will confirm the change.', 'cancelled' => 'Your appointment request was cancelled.', 'unchanged' => 'No appointment was changed. It may already be confirmed, cancelled, or unavailable.', default => 'We could not process that appointment change. Check your details and try again.' }; ?></p><?php endif; ?>
<div class="appointment-booking-card">
    <h3>Book an appointment</h3>
    <p>Select a service and preferred time. This is a request, not a confirmed booking; the care team will contact you to confirm availability. Payments are handled directly with the care team; online payment is not available.</p>
    <form class="appointment-booking-form" action="patient-appointment-action.php" method="post">
        <input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>">
        <input type="hidden" name="action" value="book">
        <label>Service<select name="service_id" required><option value="">Choose a service</option>
            <?php foreach ($services as $service): ?>
                <?php $serviceMethods = array_filter(explode(',', (string) ($service['methods'] ?? '')), static fn (string $method): bool => isset($paymentMethodLabels[$method])); ?>
                <option value="<?= htmlspecialchars($service['id'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($service['name']) ?> — <?= $service['price_rwf'] === null ? 'Price to be confirmed' : number_format((int) $service['price_rwf']) . ' RWF' ?><?= $serviceMethods ? ' · ' . htmlspecialchars(implode(', ', array_map(static fn (string $method): string => $paymentMethodLabels[$method], $serviceMethods))) : '' ?></option>
            <?php endforeach; ?>
        </select></label>
        <label>Appointment type<select name="appointment_type" required><option value="consultation">Consultation</option><option value="follow_up">Follow-up</option><option value="lab_test">Lab test</option></select></label>
        <label>Doctor<select name="doctor_email"><option value="">No preference</option><?php foreach ($doctors as $doctor): ?><option value="<?= htmlspecialchars($doctor['email'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($doctor['full_name']) ?></option><?php endforeach; ?></select></label>
        <label>Preferred date and time<input type="datetime-local" name="preferred_at" min="<?= htmlspecialchars(date('Y-m-d\\TH:i', strtotime('+2 hours')), ENT_QUOTES, 'UTF-8') ?>" max="<?= htmlspecialchars(date('Y-m-d\\TH:i', strtotime('+1 year')), ENT_QUOTES, 'UTF-8') ?>" required></label>
        <label class="appointment-form-wide">Notes for the care team<textarea name="message" maxlength="1000" rows="3" placeholder="Optional details for your request"></textarea></label>
        <button class="button appointment-form-wide" type="submit">Request appointment <span aria-hidden="true">&#8599;</span></button>
    </form>
    <h3>Payment details by service</h3>
    <?php foreach ($services as $service): ?>
        <?php $serviceMethods = array_filter(explode(',', (string) ($service['methods'] ?? '')), static fn (string $method): bool => isset($paymentMethodLabels[$method])); ?>
        <?php if ($serviceMethods): ?>
            <div class="patient-call-card"><div>
                <strong><?= htmlspecialchars($service['name']) ?></strong>
                <p><?= $service['price_rwf'] === null ? 'Price to be confirmed' : number_format((int) $service['price_rwf']) . ' RWF' ?></p>
                <?php foreach (payment_destination_lines($serviceMethods, $paymentDestinations) as $paymentLine): ?><p><?= htmlspecialchars($paymentLine) ?></p><?php endforeach; ?>
            </div></div>
        <?php endif; ?>
    <?php endforeach; ?>
</div>
<div class="appointment-list-block"><h3>Upcoming appointments &amp; requests</h3><?php if (!$activeAppointments): ?><p class="empty-state">No upcoming appointments or requests.</p><?php else: ?><div class="patient-appointment-list"><?php foreach ($activeAppointments as $appointment): ?><article class="patient-appointment-card"><div class="patient-appointment-summary"><span class="status-badge status-<?= htmlspecialchars($appointment['status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars(ucfirst($appointment['status'])) ?></span><h4><?= htmlspecialchars($appointment['service_name']) ?></h4><p><?= htmlspecialchars(ucfirst(str_replace('_', ' ', (string) ($appointment['appointment_type'] ?? 'consultation')))) ?><?php if ($appointment['preferred_at']): ?> · Preferred <?= htmlspecialchars(date('j M Y, H:i', strtotime($appointment['preferred_at']))) ?><?php else: ?> · Time to be arranged<?php endif; ?></p><p><?= htmlspecialchars($appointment['doctor_name'] ?: ($appointment['doctor_email'] ?: 'Doctor preference: none')) ?></p><?php if ($appointment['status'] !== 'scheduled'): ?><small>Pending confirmation by the care team.</small><?php endif; ?></div><div class="patient-appointment-actions"><form action="patient-appointment-action.php" method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="reschedule"><input type="hidden" name="appointment_id" value="<?= htmlspecialchars($appointment['id'], ENT_QUOTES, 'UTF-8') ?>"><label class="sr-only" for="reschedule-<?= htmlspecialchars($appointment['id'], ENT_QUOTES, 'UTF-8') ?>">New preferred date and time</label><input id="reschedule-<?= htmlspecialchars($appointment['id'], ENT_QUOTES, 'UTF-8') ?>" type="datetime-local" name="preferred_at" min="<?= htmlspecialchars(date('Y-m-d\\TH:i', strtotime('+2 hours')), ENT_QUOTES, 'UTF-8') ?>" required><button class="button button-small" type="submit">Reschedule request</button></form><form action="patient-appointment-action.php" method="post" onsubmit="return confirm('Cancel this appointment request?')"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="appointment_id" value="<?= htmlspecialchars($appointment['id'], ENT_QUOTES, 'UTF-8') ?>"><button class="text-link" type="submit">Cancel request</button></form></div></article><?php endforeach; ?></div><?php endif; ?></div>
<div class="appointment-list-block"><h3>Past &amp; cancelled requests</h3><?php if (!$pastAppointments): ?><p class="empty-state">Completed visit history and summaries will appear when connected to your clinical record.</p><?php else: ?><div class="patient-appointment-list"><?php foreach ($pastAppointments as $appointment): ?><article class="patient-appointment-card"><div><span class="status-badge status-<?= htmlspecialchars($appointment['status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars(ucfirst($appointment['status'])) ?></span><h4><?= htmlspecialchars($appointment['service_name']) ?></h4><p><?= $appointment['preferred_at'] ? htmlspecialchars(date('j M Y, H:i', strtotime($appointment['preferred_at']))) : 'No preferred time recorded' ?></p><?php if ($appointment['status'] !== 'cancelled'): ?><small>Visit summaries, prescriptions and lab-result links are not connected.</small><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></div>
